@push('js')
<script>
document.querySelectorAll('.pay-teacher').forEach(b=>b.addEventListener('click',()=>{document.getElementById('teacherPayForm').action=b.dataset.action;document.getElementById('teacherInfo').textContent=b.dataset.name+' - '+b.dataset.activity+' - '+b.dataset.unit;}));
document.querySelectorAll('.budget-edit').forEach(b=>b.addEventListener('click',()=>{const isActivity=b.dataset.level==='activity',amount=document.getElementById('budgetEditAmount');document.getElementById('budgetEditForm').action=b.dataset.action;document.getElementById('budgetEditCode').value=b.dataset.code||'';document.getElementById('budgetEditDescription').value=b.dataset.description||'';document.getElementById('budgetEditType').textContent=isActivity?'Kegiatan induk':'Subkegiatan / rincian anggaran';amount.value=isActivity?0:(b.dataset.amount||0);amount.disabled=isActivity;document.getElementById('budgetEditAmountHelp').textContent=isActivity?'Total kegiatan dihitung otomatis dari seluruh rincian.':'Perubahan nominal langsung memperbarui total kegiatan induk.';}));document.querySelectorAll('.status-btn').forEach(b=>b.addEventListener('click',()=>{document.getElementById('statusForm').action=b.dataset.action;document.getElementById('statusName').textContent=b.dataset.name;document.getElementById('statusValue').value=b.dataset.status;document.getElementById('referenceValue').value=b.dataset.reference||'';document.getElementById('noteValue').value=b.dataset.note||'';}));
const level=document.getElementById('budgetLevel'),parent=document.getElementById('budgetParent'),amount=document.getElementById('budgetAmount'),amountHelp=document.getElementById('budgetAmountHelp');function filterParents(){const wanted=level.value==='subactivity'?'activity':level.value==='account'?'subactivity':'';[...parent.options].forEach((o,i)=>{if(i)o.hidden=!wanted||o.dataset.level!==wanted});parent.value='';parent.disabled=!wanted;const isParent=level.value==='activity';amount.disabled=isParent;if(isParent)amount.value=0;amountHelp.textContent=isParent?'Total kegiatan dihitung otomatis dari seluruh rincian di bawahnya.':'Masukkan pagu untuk rincian anggaran ini.';}level.addEventListener('change',filterParents);filterParents();
document.getElementById('budgetForm')?.addEventListener('submit',function(){const button=this.querySelector('button[type=submit],button:not([type])');if(button){button.disabled=true;button.innerHTML='<i class="bx bx-loader bx-spin me-1"></i>Menyimpan...';}});
</script>
@endpush
